#include "ax_akm.h"
#include "ax_robot.h"

/**
  * @简  述  根据阿克曼前进和转向速度转换为前轮转向角度
  * @参  数  vx  前进速度，单位m/s 
  *          vw  转向速度，单位rad/s
  * @返回值  右前轮转向角度，单位rad
  */
/* @L37 函数契约 ------------------------------------------------
 *  vx  0.001 m/s   前进速度（倒车为负）
 *  vw  0.001 rad/s 横摆角速度（左正右负，与 ROS REP-103 一致）
 *  返回 0.001 rad  前轮转角（虚拟中心轮，右正左负？—— 符号由下游舵机负号决定）
 * 实现是纯粹的"曲率 = 角速度/线速度"几何，没有任何动力学/侧滑补偿。
 * ------------------------------------------------------------- */
int16_t AX_AKM_WToAngle(int16_t vx, int16_t vw) 
{
    float akm_angle; //前轮转向角度
	float radius;  //转弯半径

/* @L42 为什么必须两个都非零 -------------------------------------
 * 只要 vx==0，无论 vw 多大都返回 0：真实阿克曼无法原地转向，
 * 强行打舵只会让轮胎拖地。所以"倒车掉头"必须是 vx<0 且 vw≠0 的组合。
 * 推论（S4 的根因之一）：Nav2 默认的 Spin / RotateToGoal 行为在这台车上
 * 天然失效，必须换行为树或让规划器直接给出带倒车的路径。
 * ------------------------------------------------------------- */
	if(vw!=0 && vx!=0)
	{
		//计算转弯半径
/* @L45 单位自洽的小技巧 -----------------------------------------
 * R = v/ω。看似"0.001 m/s ÷ 0.001 rad/s = m"是因为两个 1000 恰好约掉，
 * 如果哪天把其中一个改成 SI 浮点、另一个仍是 0.001 定点，这里就会悄悄错 1000 倍。
 * 这类"靠约定抵消"的写法是嵌入式里最常见的隐患，读的时候要立刻确认两边同尺度。
 * ------------------------------------------------------------- */
		radius =  (float)vx/(float)vw;
		
		//转弯半径小于最小转弯
/* @L48 最小转弯半径钳位（含符号处理）----------------------------
 * 正向和负向各钳一次，负半径代表向另一侧转（倒车时符号会反过来）。
 * 0.35 m 来自 ax_robot.h:155，注释写的是 L·cot30° - W/2 = 0.146×1.732-0.08
 * ≈ 0.173 m，与 0.35 对不上 —— 厂商注释与实际取值不一致（可能改过机械）。
 * 手册标称 0.55 m -> 三个数（0.173 / 0.35 / 0.55）互相矛盾，S8 实测裁决。
 * ------------------------------------------------------------- */
		if(radius>0 && radius<AKM_TURN_R_MINI)
		{
			radius = AKM_TURN_R_MINI; 
		}
			
		if(radius<0 && radius>(-AKM_TURN_R_MINI))
		{
			radius = -AKM_TURN_R_MINI;
		}		

		//计算机器人前轮转向角度,单位弧度
/* @L59 转弯半径 -> 前轮转角 -------------------------------------
 *   δ = atan(L / R)
 * 与 ax_kinematics.c:96 的 R=L/tan(δ) 互为反函数 —— 上下位机各存了一份，
 * 改轴距时必须两处一起改，否则"下发的 vw"和"实际轨迹"会不一致。
 * ------------------------------------------------------------- */
		akm_angle = atan(AKM_ACLE_BASE/(radius));
	}
	else
	{
		akm_angle = 0;
	}
	
/* @L66 ★ 返回单位：0.001 rad ★ ---------------------------------
 * 这一行是整个协议里最容易被误解的约定：
 *   返回值 235 表示 0.235 rad = 13.5°，不是 235°。
 * ax_kinematics.c:93 除以 1000 还原成弧度后直接进 tan()。
 * 你在排"舵机映射"问题时的第一个检查点就应该是这里。
 * ------------------------------------------------------------- */
	return (akm_angle*1000);
}

